// SPDX-License-Identifier: MIT
// Sluicegate (Prismheart campaign), plain C++17 for the Unreal binding. A port of tools/minigames/sluicegate.py
// (unreal-team), which stays the rules authority. Seeding is CPython-compatible (DaedalusPyRandomCore.h,
// "sluicegate:<seed>:<difficulty>") and the only draws are randrange at setup; nothing is random after. Byte parity
// goes through engines/unreal/core-test/sluicegate_parity.txt (sluicegate_core_test.cpp), generated by
// tools/minigames/sluicegate_parity.py.
//
// Rules: an S x S field of channels and rock. Water enters at the headgate (row 0, middle column); each turn the
// headgate pushes Flow more cells of water into the nearest dry open channels (wet cells in the order they were
// wetted, neighbours n/e/s/w) and closes after Turns turns. Before each push the player drops one gate on a dry
// channel cell (a limited stock) or waits. Water reaching a cistern fills it; reaching the mill wheel floods it and
// loses. Every cistern filled wins (+CisternScore each, +GateBonus per gate left, +TurnBonus per turn left); the
// headgate closing or the flow stopping with a cistern dry loses. Every field is winnable: the mill is a dead end
// whose throat can be gated without cutting a cistern off, and cisterns sit inside the turn budget.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <array>
#include <cstdint>
#include <string>
#include <vector>

namespace daedalus { namespace sluicegate {

inline const char* GameId() { return "sluicegate"; }
inline const char* Title() { return "Sluicegate"; }

constexpr int MaxSize = 12;
constexpr int Rock = 0, Channel = 1;
constexpr int CisternScore = 10, GateBonus = 3, TurnBonus = 1;
constexpr int MinCisternDistance = 2, MinMillDistance = 3, CisternSlack = 3;
constexpr int MaxAttempts = 40;   // fields drawn before setup gives up on finding a wheel the idle flow threatens

struct Difficulty { const char* Name; int Size; int Cisterns; int Gates; int Flow; int Turns; int ChannelPct; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 7, 3, 4, 2, 9, 70 }, { "normal", 8, 4, 5, 2, 12, 68 }, { "hard", 9, 5, 6, 2, 15, 66 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

struct Cell { int R = 0, C = 0; bool operator==(const Cell& O) const noexcept { return R == O.R && C == O.C; } bool operator!=(const Cell& O) const noexcept { return !(*this == O); } };
constexpr Cell NoCell{ -1, -1 };

/** The four neighbours in the rules' order: n, e, s, w. */
constexpr int NeighbourDR[] = { -1, 0, 1, 0 };
constexpr int NeighbourDC[] = { 0, 1, 0, -1 };

/** Breadth-first distances from the wet cells; -1 is unreachable. */
using DistanceMap = std::array<std::array<int, MaxSize>, MaxSize>;
/** A cell set as a bitmap, for gates and wetness during a search. */
using CellMask = std::array<std::array<bool, MaxSize>, MaxSize>;

/** How one no-more-gates rollout ends (Game.rollout). */
struct Ending { bool Won = false, Flooded = false; int Filled = 0, Used = 0; };

struct Game
{
	const Difficulty* Diff = nullptr;
	std::array<std::array<int, MaxSize>, MaxSize> Field{};
	Cell Head;
	std::vector<Cell> Cisterns, Wet, Gates;   // Wet in wetting order: the next push walks it front to back
	Cell Mill = NoCell;
	int GatesLeft = 0, Filled = 0, Turns = 0;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	enum class Act { Ok, BadCell, NoGates, NotGateable, GameOver };

	int Size() const noexcept { return Diff ? Diff->Size : 0; }
	bool Inside(Cell X) const noexcept { return X.R >= 0 && X.R < Size() && X.C >= 0 && X.C < Size(); }
	bool IsChannel(Cell X) const noexcept { return Inside(X) && Field[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)] == Channel; }
	static bool Has(const std::vector<Cell>& V, Cell X) noexcept { for (const Cell& Y : V) if (Y == X) return true; return false; }
	bool IsWet(Cell X) const noexcept { return Has(Wet, X); }
	bool IsCistern(Cell X) const noexcept { return Has(Cisterns, X); }
	bool IsGate(Cell X) const noexcept { return Has(Gates, X); }
	int MinReach() const noexcept { return Size() * Size() / 3; }
	int SlackTurns() const noexcept { return Diff ? std::max(CisternSlack, Diff->Turns / 3) : CisternSlack; }
	int DryCisterns() const noexcept { return static_cast<int>(Cisterns.size()) - Filled; }
	/** Game.fresh: no push yet, so the screen shows its tutorial rows. */
	bool FreshField() const noexcept { return Diff && Turns == Diff->Turns && !Over; }

	/** Game.gateable: a dry channel cell that is not the headgate, a cistern, the mill or already gated. */
	bool Gateable(Cell X) const noexcept
	{
		return IsChannel(X) && !IsWet(X) && !IsGate(X) && !IsCistern(X) && X != Mill && X != Head;
	}

	/** Game._distances: breadth-first from the wet cells through open channels; gated cells block. */
	void Distances(const CellMask& Gated, DistanceMap& Out) const
	{
		for (auto& Row : Out) Row.fill(-1);
		std::array<Cell, MaxSize * MaxSize> Queue{};
		int HeadIdx = 0, Tail = 0;
		for (const Cell& W : Wet) { Out[static_cast<size_t>(W.R)][static_cast<size_t>(W.C)] = 0; Queue[Tail++] = W; }
		while (HeadIdx < Tail)
		{
			const Cell X = Queue[HeadIdx++];
			for (int N = 0; N < 4; ++N)
			{
				const Cell Y{ X.R + NeighbourDR[N], X.C + NeighbourDC[N] };
				if (!IsChannel(Y) || Out[static_cast<size_t>(Y.R)][static_cast<size_t>(Y.C)] >= 0 || Gated[static_cast<size_t>(Y.R)][static_cast<size_t>(Y.C)]) continue;
				Out[static_cast<size_t>(Y.R)][static_cast<size_t>(Y.C)] = Out[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)] + 1;
				Queue[Tail++] = Y;
			}
		}
	}

	CellMask GateMask(const Cell* Extra = nullptr) const noexcept
	{
		CellMask M{};
		for (const Cell& G : Gates) M[static_cast<size_t>(G.R)][static_cast<size_t>(G.C)] = true;
		if (Extra) M[static_cast<size_t>(Extra->R)][static_cast<size_t>(Extra->C)] = true;
		return M;
	}

	/**
	 * PrismGame.start + Game.setup: draw fields until one has a mill the idle flow threatens (v2, cross-test fix), so
	 * waiting every turn never wins and every field has a wheel. False on an unknown difficulty.
	 */
	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff || Diff->Size > MaxSize) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		for (int Attempt = 0; Attempt < MaxAttempts; ++Attempt)
		{
			DrawField();
			DistanceMap Dist;
			Distances(CellMask{}, Dist);
			std::vector<Cell> Far;   // row-major, like Python's sorted()
			for (int R = 0; R < Diff->Size; ++R)
				for (int C = 0; C < Diff->Size; ++C)
				{
					const int D = Dist[static_cast<size_t>(R)][static_cast<size_t>(C)];
					if (D >= MinCisternDistance && D <= Diff->Turns - SlackTurns()) Far.push_back({ R, C });
				}
			Cisterns.clear();
			const int Want = std::min(Diff->Cisterns, static_cast<int>(Far.size()));
			while (static_cast<int>(Cisterns.size()) < Want)
			{
				const Cell X = Far[Rng.RandRange(static_cast<std::uint32_t>(Far.size()))];
				if (!IsCistern(X)) Cisterns.push_back(X);
			}
			Mill = PlaceMill(Dist);
			if (Mill != NoCell && static_cast<int>(Cisterns.size()) == Diff->Cisterns) return true;
		}
		return true;
	}

	/** Game._draw_field: the channel/rock field, the headgate, and a carved channel when the reach is cramped. */
	void DrawField()
	{
		const int S = Diff->Size;
		for (int R = 0; R < S; ++R)
			for (int C = 0; C < S; ++C)
				Field[static_cast<size_t>(R)][static_cast<size_t>(C)] = static_cast<int>(Rng.RandRange(100)) < Diff->ChannelPct ? Channel : Rock;
		Head = { 0, S / 2 };
		Field[0][static_cast<size_t>(S / 2)] = Channel;
		Wet.clear(); Wet.push_back(Head);
		Gates.clear(); GatesLeft = Diff->Gates; Turns = Diff->Turns;
		Cisterns.clear(); Filled = 0; Mill = NoCell;
		DistanceMap Dist;
		Distances(CellMask{}, Dist);
		while (Reached(Dist) < MinReach())
		{
			Cell X = Head;
			for (int Step = 0; Step < 2 * S; ++Step)
			{
				const int N = static_cast<int>(Rng.RandRange(4));
				const Cell Y{ X.R + NeighbourDR[N], X.C + NeighbourDC[N] };
				if (Inside(Y)) { X = Y; Field[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)] = Channel; }
			}
			Distances(CellMask{}, Dist);
		}
	}

	/** Game._idle_flow_wins: does waiting every turn fill every cistern before the flow reaches `MillCell`? */
	bool IdleFlowWins(Cell MillCell)
	{
		const Cell SavedMill = Mill;
		int& Tile = Field[static_cast<size_t>(MillCell.R)][static_cast<size_t>(MillCell.C)];
		const int SavedTile = Tile;
		Mill = MillCell; Tile = Channel;
		const bool IdleWon = Rollout(NoCell).Won;
		Mill = SavedMill; Tile = SavedTile;
		return IdleWon;
	}

	static int Reached(const DistanceMap& Dist) noexcept
	{
		int N = 0;
		for (const auto& Row : Dist) for (int D : Row) if (D >= 0) ++N;
		return N;
	}

	/** Game._place_mill: a dead end three or more steps out whose throat can be gated without cutting a cistern off. */
	Cell PlaceMill(const DistanceMap& Dist)   // not const: IdleFlowWins carves and restores the candidate cell
	{
		const int S = Size();
		const auto ThroatOk = [&](Cell Throat)
		{
			if (IsCistern(Throat) || Throat == Head) return false;
			CellMask Block{}; Block[static_cast<size_t>(Throat.R)][static_cast<size_t>(Throat.C)] = true;
			DistanceMap Reach; Distances(Block, Reach);
			for (const Cell& C : Cisterns) if (Reach[static_cast<size_t>(C.R)][static_cast<size_t>(C.C)] < 0) return false;
			return true;
		};
		const auto ChannelNeighbours = [&](Cell X, std::array<Cell, 4>& Out)
		{
			int N = 0;
			for (int K = 0; K < 4; ++K)
			{
				const Cell Y{ X.R + NeighbourDR[K], X.C + NeighbourDC[K] };
				if (IsChannel(Y)) Out[static_cast<size_t>(N++)] = Y;
			}
			return N;
		};
		const auto DistAt = [&](Cell X) { return Dist[static_cast<size_t>(X.R)][static_cast<size_t>(X.C)]; };
		std::vector<Cell> Candidates;
		std::array<Cell, 4> Around{};
		for (int R = 0; R < S; ++R)
			for (int C = 0; C < S; ++C)
			{
				const Cell X{ R, C };
				if (DistAt(X) < MinMillDistance || IsCistern(X)) continue;
				if (ChannelNeighbours(X, Around) == 1 && ThroatOk(Around[0])) Candidates.push_back(X);
			}
		if (Candidates.empty())   // carve: a rock cell touching exactly one channel cell that works as a throat
			for (int R = 0; R < S; ++R)
				for (int C = 0; C < S; ++C)
				{
					const Cell X{ R, C };
					if (IsChannel(X) || ChannelNeighbours(X, Around) != 1) continue;
					if (DistAt(Around[0]) >= MinMillDistance - 1 && ThroatOk(Around[0])) Candidates.push_back(X);
				}
		if (Candidates.empty())   // last resort: a rock cell with two gateable throats
			for (int R = 0; R < S; ++R)
				for (int C = 0; C < S; ++C)
				{
					const Cell X{ R, C };
					if (IsChannel(X) || ChannelNeighbours(X, Around) != 2) continue;
					if (DistAt(Around[0]) >= 0 && DistAt(Around[1]) >= 0 && ThroatOk(Around[0]) && ThroatOk(Around[1])) Candidates.push_back(X);
				}
		std::vector<Cell> Threatened;   // only wheels the idle flow would reach (or fields idle flow loses anyway)
		for (const Cell& X : Candidates) if (!IdleFlowWins(X)) Threatened.push_back(X);
		if (Threatened.empty()) return NoCell;   // the caller draws another field
		const Cell M = Threatened[Rng.RandRange(static_cast<std::uint32_t>(Threatened.size()))];
		Field[static_cast<size_t>(M.R)][static_cast<size_t>(M.C)] = Channel;
		return M;
	}

	/**
	 * Game.push: the cells one turn's flow would wet from `WetList` with `Gated` in place: at most Flow, nearest first,
	 * walking the wet list in wetting order and neighbours n/e/s/w. Appends to `Out`, returns how many.
	 */
	int Push(const std::vector<Cell>& WetList, const CellMask& Gated, std::vector<Cell>& Out) const
	{
		CellMask Seen{};
		for (const Cell& W : WetList) Seen[static_cast<size_t>(W.R)][static_cast<size_t>(W.C)] = true;
		const size_t Before = Out.size();
		const int Flow = Diff->Flow;
		std::vector<Cell> Frontier = WetList, Next;
		while (!Frontier.empty() && static_cast<int>(Out.size() - Before) < Flow)
		{
			Next.clear();
			for (const Cell& X : Frontier)
				for (int N = 0; N < 4; ++N)
				{
					const Cell Y{ X.R + NeighbourDR[N], X.C + NeighbourDC[N] };
					if (!IsChannel(Y) || Seen[static_cast<size_t>(Y.R)][static_cast<size_t>(Y.C)] || Gated[static_cast<size_t>(Y.R)][static_cast<size_t>(Y.C)]) continue;
					Seen[static_cast<size_t>(Y.R)][static_cast<size_t>(Y.C)] = true;
					Out.push_back(Y); Next.push_back(Y);
					if (static_cast<int>(Out.size() - Before) == Flow) return Flow;
				}
			Frontier.swap(Next);
		}
		return static_cast<int>(Out.size() - Before);
	}

	/** Game.act. `Gate` is NoCell for a wait. `Result` mirrors the Python result text. */
	Act Step(Cell Gate, int& Reached, int& NewlyFilled, std::string& Result)
	{
		Reached = NewlyFilled = 0;
		if (Over) return Act::GameOver;
		const bool Waiting = Gate == NoCell;
		if (!Waiting)
		{
			if (GatesLeft <= 0) return Act::NoGates;
			if (!Gateable(Gate)) return Inside(Gate) ? Act::NotGateable : Act::BadCell;
			Gates.push_back(Gate); --GatesLeft;
		}
		std::vector<Cell> New;
		Reached = Push(Wet, GateMask(), New);
		Wet.insert(Wet.end(), New.begin(), New.end());
		--Turns;
		bool Flooded = false;
		for (const Cell& X : New) { if (IsCistern(X)) ++NewlyFilled; if (X == Mill) Flooded = true; }
		Filled += NewlyFilled;
		Score += CisternScore * NewlyFilled;
		const std::string Lead = (Waiting ? std::string("wait") : std::to_string(Gate.R) + "," + std::to_string(Gate.C)) + ": " + std::to_string(Reached) + " cells wet, " + std::to_string(NewlyFilled) + " filled";
		if (Flooded) { Over = true; Won = false; Result = Lead + "; the mill wheel floods"; return Act::Ok; }
		if (Filled == static_cast<int>(Cisterns.size()))
		{
			Score += GateBonus * GatesLeft + TurnBonus * Turns;
			Over = Won = true; Result = Lead + "; every cistern brims"; return Act::Ok;
		}
		if (Reached == 0 || Turns <= 0)
		{
			Over = true; Won = false;
			Result = Lead + (Reached == 0 ? "; the channel runs dry" : "; the headgate closes");
			return Act::Ok;
		}
		Result = Lead;
		return Act::Ok;
	}

	/** Game.preview: what `Gate` (NoCell = wait) would wet now; false when illegal. */
	bool Preview(Cell Gate, std::vector<Cell>& Reached, int& NewlyFilled, bool& Flooded) const
	{
		Reached.clear(); NewlyFilled = 0; Flooded = false;
		if (Over) return false;
		const bool Waiting = Gate == NoCell;
		if (!Waiting && (GatesLeft <= 0 || !Gateable(Gate))) return false;
		Push(Wet, GateMask(Waiting ? nullptr : &Gate), Reached);
		for (const Cell& X : Reached) { if (IsCistern(X)) ++NewlyFilled; if (X == Mill) Flooded = true; }
		return true;
	}

	/** Game.rollout: play the rest of the flow with no more gates after `Extra` (NoCell = none). */
	Ending Rollout(Cell Extra) const
	{
		const CellMask Gated = GateMask(Extra == NoCell ? nullptr : &Extra);
		std::vector<Cell> WetList = Wet, New;
		Ending E; E.Filled = Filled;
		int TurnsLeft = Turns;
		while (TurnsLeft > 0)
		{
			New.clear();
			const int Reached = Push(WetList, Gated, New);
			WetList.insert(WetList.end(), New.begin(), New.end());
			--TurnsLeft;
			for (const Cell& X : New) { if (IsCistern(X)) ++E.Filled; if (X == Mill) E.Flooded = true; }
			if (E.Flooded) break;
			if (E.Filled == static_cast<int>(Cisterns.size())) { E.Won = true; break; }
			if (Reached == 0) break;
		}
		E.Used = Turns - TurnsLeft;
		return E;
	}

	/** Game.demo_action, the gatekeeper: every gate (and waiting) gets a rollout; the best ending wins, ties by row, column. */
	Cell DemoAction() const
	{
		Cell Best = NoCell;
		Ending BestEnd = Rollout(NoCell);
		if (GatesLeft > 0)
			for (int R = 0; R < Size(); ++R)
				for (int C = 0; C < Size(); ++C)
				{
					const Cell X{ R, C };
					if (!Gateable(X)) continue;
					const Ending E = Rollout(X);
					if (Better(E, BestEnd)) { BestEnd = E; Best = X; }
				}
		return Best;
	}

	/** Game._key, strictly less: won, then not flooded, then more filled, then fewer turns used. */
	static bool Better(const Ending& A, const Ending& B) noexcept
	{
		if (A.Won != B.Won) return A.Won;
		if (A.Flooded != B.Flooded) return !A.Flooded;
		if (A.Filled != B.Filled) return A.Filled > B.Filled;
		return A.Used < B.Used;
	}

	static std::string CellsString(const std::vector<Cell>& V)
	{
		if (V.empty()) return "-";
		std::string Out;
		for (size_t I = 0; I < V.size(); ++I) { if (I) Out.push_back(';'); Out += std::to_string(V[I].R) + "," + std::to_string(V[I].C); }
		return Out;
	}
	std::string FieldString() const
	{
		std::string Out;
		for (int R = 0; R < Size(); ++R)
		{
			if (R) Out.push_back(';');
			for (int C = 0; C < Size(); ++C) Out.push_back(Field[static_cast<size_t>(R)][static_cast<size_t>(C)] == Channel ? '.' : '#');
		}
		return Out;
	}
};

} } // namespace daedalus::sluicegate
